  /// Convertit le nom d'espèce en nom de fichier (espaces → underscores)
  static String _toFileName(String species) => species.replaceAll(' ', '_');

  /// Chemin vers l'image de base d'une espèce
  static String? getImageAssetPath(String species) {
    if (speciesWithImages.contains(species)) {
      return 'assets/images/dinos/${_toFileName(species)}_ASA.png';
    }
    return null;
  }

  /// Chemin vers le masque d'une espèce
  static String? getMaskAssetPath(String species) {
    if (speciesWithMasks.contains(species)) {
      return 'assets/images/dinos/${_toFileName(species)}_ASA_m.png';
    }
    return null;
  }

  /// Vérifier si une espèce a une image
  static bool hasImage(String species) => speciesWithImages.contains(species);

  /// Vérifier si une espèce a un masque
  static bool hasMask(String species) => speciesWithMasks.contains(species);
